    fn eval_sequence_start_step() {
        let (cm, vs) = make_test_env();
        let (r, c, data) = unwrap_array(eval_str("=SEQUENCE(3, 1, 10, 2)", &cm, &vs));
        assert_eq!((r, c), (3, 1));
        assert_eq!(
            data,
            vec![
                Value::Number(10.0),
                Value::Number(12.0),
                Value::Number(14.0)
            ]
        );
    }

