    #[test]
    fn eval_choosecols_basic() {
        let (cm, vs) = make_test_env();
        // SEQUENCE(2, 3) = [[1,2,3],[4,5,6]]. CHOOSECOLS(1, 3) → [[1,3],[4,6]].
        let (r, c, data) = unwrap_array(eval_str("=CHOOSECOLS(SEQUENCE(2, 3), 1, 3)", &cm, &vs));
        assert_eq!((r, c), (2, 2));
        assert_eq!(
            data,
            vec![
                Value::Number(1.0),
                Value::Number(3.0),
                Value::Number(4.0),
                Value::Number(6.0),
            ]
        );
    }

