    /// Negative `instance_num` counts from the right. -1 = last occurrence.
    #[test]
    fn eval_textbefore_negative_instance() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=TEXTBEFORE(\"a-b-c-d\", \"-\", -1)", &cm, &vs),
            Value::Text("a-b-c".into())
        );
        assert_eq!(
            eval_str("=TEXTAFTER(\"a-b-c-d\", \"-\", -1)", &cm, &vs),
            Value::Text("d".into())
        );
    }

    /// Not-found surfaces `#N/A` when no `if_not_found` arg is supplied,
    /// and the custom value when one is.
    #[test]
    fn eval_textbefore_not_found_default_and_custom() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=TEXTBEFORE(\"abc\", \"-\")", &cm, &vs),
            Value::Error(ValueError::NotAvailable)
        );
        assert_eq!(
            eval_str("=TEXTBEFORE(\"abc\", \"-\", 1, 0, 0, \"miss\")", &cm, &vs),
            Value::Text("miss".into())
        );
    }

    #[test]
    fn eval_textbefore_after_lazy_error_fallback() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=TEXTBEFORE(\"a-b\", \"-\", 1, 0, 0, #N/A)", &cm, &vs),
            Value::Text("a".into())
        );
        assert_eq!(
            eval_str("=TEXTAFTER(\"a-b\", \"-\", 1, 0, 0, 1/0)", &cm, &vs),
            Value::Text("b".into())
        );
        assert_eq!(
            eval_str("=TEXTBEFORE(\"ab\", \"-\", 1, 0, 0, #N/A)", &cm, &vs),
            Value::Error(ValueError::NotAvailable)
        );
    }

    /// Case-insensitive mode (1) lets `"X"` match `"x"`.
    #[test]
    fn eval_textbefore_case_insensitive() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=TEXTBEFORE(\"axb\", \"X\", 1, 1)", &cm, &vs),
            Value::Text("a".into())
        );
        // Without insensitive mode, no match.
        assert_eq!(
            eval_str("=TEXTBEFORE(\"axb\", \"X\")", &cm, &vs),
            Value::Error(ValueError::NotAvailable)
        );
    }

    #[test]
    fn broadcast_comparison_returns_boolean_array() {
        let (cm, vs) = make_broadcast_env();
        let v = eval_str("=A1:A5>15", &cm, &vs);
        let (rows, cols, data) = broadcast_unwrap_array(v);
        assert_eq!((rows, cols), (5, 1));
        // 10>15=F, 20>15=T, 30>15=T, 40>15=T, 50>15=T
        assert_eq!(
            data,
            vec![
                Value::Boolean(false),
                Value::Boolean(true),
                Value::Boolean(true),
                Value::Boolean(true),
                Value::Boolean(true),
            ]
        );
    }

    #[test]
    fn eval_textbefore_arg_count_error() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=TEXTBEFORE(\"abc\")", &cm, &vs),
            Value::Error(ValueError::WrongArgCount)
        );
    }

    /// match_end=1 treats end-of-string as a virtual match, so the last
    /// occurrence is the implicit endpoint.
    #[test]
    fn eval_textafter_match_end() {
        let (cm, vs) = make_test_env();
        // "a-b" has matches at byte 0 (virtual start), byte 1 (real "-"),
        // byte 3 (virtual end). instance=-1 picks byte 3 → "".
        assert_eq!(
            eval_str("=TEXTAFTER(\"a-b\", \"-\", -1, 0, 1)", &cm, &vs),
            Value::Text("".into())
        );
    }

    // === LOOKUP ===

    /// LOOKUP vector form, 3-arg. Exact match returns the parallel
    /// element.
    #[test]
    fn eval_lookup_vector_form_exact() {
        let (cm, vs) = make_test_env();
        // Keys: 1,2,3,4; Results: "a","b","c","d". LOOKUP(3,...) → "c".
        assert_eq!(
            eval_str("=LOOKUP(3, {1,2,3,4}, {\"a\",\"b\",\"c\",\"d\"})", &cm, &vs),
            Value::Text("c".into())
        );
    }

    /// LOOKUP picks the largest key ≤ needle (approximate walk).
    #[test]
    fn eval_lookup_vector_approximate() {
        let (cm, vs) = make_test_env();
        // Keys 1,3,5,7. needle=4 → largest ≤ is 3 → "b".
        assert_eq!(
            eval_str("=LOOKUP(4, {1,3,5,7}, {\"a\",\"b\",\"c\",\"d\"})", &cm, &vs),
            Value::Text("b".into())
        );
    }

    /// LOOKUP without `result_vector` returns the matching key itself.
    #[test]
    fn eval_lookup_two_arg_vector_form() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=LOOKUP(3, {1,2,3,4})", &cm, &vs),
            Value::Number(3.0)
        );
    }

    /// LOOKUP array form: 2nd arg is 2D, longer dimension carries the
    /// lookup keys; the opposite end of the other dimension is the
    /// result. Here {1,2;3,4} is 2×2 with cols == rows, so we treat as
    /// horizontal (first row = keys, last row = result).
    #[test]
    fn eval_lookup_array_form() {
        let (cm, vs) = make_test_env();
        // 2×3 horizontal: keys 1,2,3 in row 0; results "a","b","c" in row 1.
        // LOOKUP(2, {1,2,3;"a","b","c"}) → "b".
        assert_eq!(
            eval_str("=LOOKUP(2, {1,2,3;\"a\",\"b\",\"c\"})", &cm, &vs),
            Value::Text("b".into())
        );
    }

    /// LOOKUP not found (needle smaller than every key) → #N/A.
    #[test]
    fn eval_lookup_not_found() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=LOOKUP(0, {1,2,3}, {\"a\",\"b\",\"c\"})", &cm, &vs),
            Value::Error(ValueError::NotAvailable)
        );
    }

    /// Vector lengths must agree.
    #[test]
    fn eval_lookup_shape_mismatch() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=LOOKUP(2, {1,2,3}, {\"a\",\"b\"})", &cm, &vs),
            Value::Error(ValueError::WrongType)
        );
    }

    #[test]
    fn broadcast_per_cell_error_stays_in_array() {
        // Build an env where A2 is text; A1=10, A3=30. `=A1:A3*2` should
        // produce [20, WrongType, 60] — the error sits in cell index 1
        // without poisoning the rest of the spill.
        let mut cm = HashMap::new();
        let mut vs = HashMap::new();
        let a1 = AtomId::from_raw(0);
        let a2 = AtomId::from_raw(1);
        let a3 = AtomId::from_raw(2);
        cm.insert(CellAddress::new(0, 0), a1);
        cm.insert(CellAddress::new(1, 0), a2);
        cm.insert(CellAddress::new(2, 0), a3);
        vs.insert(a1, Value::Number(10.0));
        vs.insert(a2, Value::Text("text".into()));
        vs.insert(a3, Value::Number(30.0));
        let v = eval_str("=A1:A3*2", &cm, &vs);
        let (rows, cols, data) = broadcast_unwrap_array(v);
        assert_eq!((rows, cols), (3, 1));
        assert_eq!(data[0], Value::Number(20.0));
        assert_eq!(data[1], Value::Error(ValueError::WrongType));
        assert_eq!(data[2], Value::Number(60.0));
    }

    #[test]
    fn broadcast_single_cell_range_stays_scalar() {
        // `=A1:A1+1` should match the scalar path: result is a Number,
        // NOT a 1x1 Array. This proves we don't accidentally widen
        // implicit intersection.
        let (cm, vs) = make_broadcast_env();
        assert_eq!(eval_str("=A1:A1+1", &cm, &vs), Value::Number(11.0));
    }

    #[test]
    fn eval_lookup_arg_count_error() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=LOOKUP(1)", &cm, &vs),
            Value::Error(ValueError::WrongArgCount)
        );
        assert_eq!(
            eval_str("=LOOKUP(1,2,3,4)", &cm, &vs),
            Value::Error(ValueError::WrongArgCount)
        );
    }

    // === Asian text-conversion functions (ASC / JIS / DBCS / PHONETIC) ===
    //
    // The mapping tables live in `asc_convert` / `jis_convert`. Tests
    // below cover: ASCII width swap, half/full-width katakana, voicing
    // composition / decomposition, the Excel JIS yen-sign quirk, mixed
    // text pass-through, empty input, arg count, and error propagation.

    #[test]
    fn eval_asc_ascii_round_trip() {
        let (cm, vs) = make_test_env();
        // JIS widens ASCII, ASC narrows it back — full round-trip.
        assert_eq!(
            eval_str("=ASC(JIS(\"abc\"))", &cm, &vs),
            Value::Text("abc".into())
        );
    }

    // === HYPERLINK + IMAGE ===
    //
    // Formula-level behaviour only. The host UI is responsible for turning
    // the returned text into a clickable link or rendered `<img>`. The
    // tests below assert (a) the scalar return value, (b) error
    // propagation, (c) arg-count guards, and (d) the structured-text
    // payload contract documented on the IMAGE match arm.

    /// Build a env with a URL string in A1 so HYPERLINK can read a cell.
    fn make_link_env() -> (HashMap<CellAddress, AtomId>, HashMap<AtomId, Value>) {
        let mut cm = HashMap::new();
        let mut vs = HashMap::new();
        let a1 = AtomId::from_raw(0);
        let a2 = AtomId::from_raw(1);
        cm.insert(CellAddress::new(0, 0), a1); // A1
        cm.insert(CellAddress::new(1, 0), a2); // A2
        vs.insert(a1, Value::Text("https://example.com".into()));
        vs.insert(a2, Value::Number(42.0));
        (cm, vs)
    }

    #[test]
    fn eval_hyperlink_with_friendly_name() {
        let (cm, vs) = make_link_env();
        assert_eq!(
            eval_str(
                "=HYPERLINK(\"https://example.com\", \"click me\")",
                &cm,
                &vs
            ),
            Value::Text("click me".into())
        );
    }

    #[test]
    fn eval_jis_ascii_round_trip() {
        let (cm, vs) = make_test_env();
        // ASC narrows full-width "ＡＢＣ" (U+FF21..) to "ABC", then JIS
        // widens it back — bit-for-bit identical to the input.
        assert_eq!(
            eval_str("=JIS(ASC(\"\u{FF21}\u{FF22}\u{FF23}\"))", &cm, &vs),
            Value::Text("\u{FF21}\u{FF22}\u{FF23}".into())
        );
    }

    #[test]
    fn eval_hyperlink_url_only() {
        let (cm, vs) = make_link_env();
        assert_eq!(
            eval_str("=HYPERLINK(\"https://example.com\")", &cm, &vs),
            Value::Text("https://example.com".into())
        );
    }

    #[test]
    fn eval_asc_widens_ascii_directly() {
        let (cm, vs) = make_test_env();
        // Direct narrowing: each full-width letter shifts by 0xFEE0.
        assert_eq!(
            eval_str("=ASC(\"\u{FF21}\u{FF22}\u{FF23}\")", &cm, &vs),
            Value::Text("ABC".into())
        );
    }

    #[test]
    fn eval_hyperlink_cell_ref_url() {
        let (cm, vs) = make_link_env();
        // A1 holds "https://example.com" — used as both link and label.
        assert_eq!(
            eval_str("=HYPERLINK(A1)", &cm, &vs),
            Value::Text("https://example.com".into())
        );
    }

    #[test]
    fn eval_jis_widens_ascii_directly() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=JIS(\"ABC\")", &cm, &vs),
            Value::Text("\u{FF21}\u{FF22}\u{FF23}".into())
        );
    }

    #[test]
    fn eval_hyperlink_friendly_number_coerces() {
        let (cm, vs) = make_link_env();
        // friendly_name is a Number → coerced to integer text.
        assert_eq!(
            eval_str("=HYPERLINK(A1, A2)", &cm, &vs),
            Value::Text("42".into())
        );
    }

    #[test]
    fn eval_dbcs_aliases_jis() {
        let (cm, vs) = make_test_env();
        // DBCS is the Excel-2013 alias for JIS — they must produce
        // identical output for every input.
        assert_eq!(
            eval_str("=DBCS(\"ABC\")", &cm, &vs),
            eval_str("=JIS(\"ABC\")", &cm, &vs),
        );
    }

    #[test]
    fn eval_hyperlink_propagates_error_in_link() {
        let (cm, vs) = make_link_env();
        // 1/0 in link_location short-circuits.
        assert_eq!(
            eval_str("=HYPERLINK(1/0, \"x\")", &cm, &vs),
            Value::Error(ValueError::DivisionByZero)
        );
    }

    #[test]
    fn eval_asc_voiced_katakana_decomposes() {
        let (cm, vs) = make_test_env();
        // ガ (U+30AC) → ｶ (U+FF76) + ﾞ (U+FF9E).
        assert_eq!(
            eval_str("=ASC(\"\u{30AC}\")", &cm, &vs),
            Value::Text("\u{FF76}\u{FF9E}".into())
        );
        // パ (U+30D1) → ﾊ (U+FF8A) + ﾟ (U+FF9F).
        assert_eq!(
            eval_str("=ASC(\"\u{30D1}\")", &cm, &vs),
            Value::Text("\u{FF8A}\u{FF9F}".into())
        );
        // ヴ (U+30F4) — special-cased to ｳ + ﾞ.
        assert_eq!(
            eval_str("=ASC(\"\u{30F4}\")", &cm, &vs),
            Value::Text("\u{FF73}\u{FF9E}".into())
        );
    }

    #[test]
    fn eval_hyperlink_propagates_error_in_friendly() {
        let (cm, vs) = make_link_env();
        assert_eq!(
            eval_str("=HYPERLINK(\"u\", 1/0)", &cm, &vs),
            Value::Error(ValueError::DivisionByZero)
        );
    }

    #[test]
    fn eval_jis_voiced_katakana_composes() {
        let (cm, vs) = make_test_env();
        // ｶ + ﾞ → ガ (one full-width char).
        assert_eq!(
            eval_str("=JIS(\"\u{FF76}\u{FF9E}\")", &cm, &vs),
            Value::Text("\u{30AC}".into())
        );
        // ﾊ + ﾟ → パ.
        assert_eq!(
            eval_str("=JIS(\"\u{FF8A}\u{FF9F}\")", &cm, &vs),
            Value::Text("\u{30D1}".into())
        );
        // ｳ + ﾞ → ヴ.
        assert_eq!(
            eval_str("=JIS(\"\u{FF73}\u{FF9E}\")", &cm, &vs),
            Value::Text("\u{30F4}".into())
        );
    }

    #[test]
    fn eval_hyperlink_empty_link_returns_empty() {
        let (cm, vs) = make_link_env();
        // No friendly name + empty link → empty text (Excel parity).
        assert_eq!(
            eval_str("=HYPERLINK(\"\")", &cm, &vs),
            Value::Text(String::new())
        );
    }

    #[test]
    fn eval_asc_mixed_text_passthrough() {
        let (cm, vs) = make_test_env();
        // Full-width "Ｈｅｌｌｏ" + full-width space + CJK ideographs.
        // ASCII letters and space convert; CJK passes through.
        assert_eq!(
            eval_str(
                "=ASC(\"\u{FF28}\u{FF45}\u{FF4C}\u{FF4C}\u{FF4F}\u{3000}\u{4E16}\u{754C}\")",
                &cm,
                &vs
            ),
            Value::Text("Hello \u{4E16}\u{754C}".into())
        );
    }

    #[test]
    fn eval_hyperlink_wrong_arg_count() {
        let (cm, vs) = make_link_env();
        assert_eq!(
            eval_str("=HYPERLINK()", &cm, &vs),
            Value::Error(ValueError::WrongArgCount)
        );
        assert_eq!(
            eval_str("=HYPERLINK(\"a\",\"b\",\"c\")", &cm, &vs),
            Value::Error(ValueError::WrongArgCount)
        );
    }

    #[test]
    fn eval_image_basic() {
        let (cm, vs) = make_link_env();
        assert_eq!(
            eval_str("=IMAGE(\"https://example.com/cat.jpg\")", &cm, &vs),
            Value::Text("<IMAGE: https://example.com/cat.jpg>".into())
        );
    }

    #[test]
    fn eval_image_with_alt() {
        let (cm, vs) = make_link_env();
        assert_eq!(
            eval_str(
                "=IMAGE(\"https://example.com/cat.jpg\", \"a cat\")",
                &cm,
                &vs
            ),
            Value::Text("<IMAGE: https://example.com/cat.jpg alt=\"a cat\">".into())
        );
    }

    #[test]
    fn eval_asc_yen_sign_becomes_backslash() {
        let (cm, vs) = make_test_env();
        // U+FFE5 ￥ → U+005C \ per Excel's JIS code page convention.
        // Despite the glyph, the byte is backslash in CP932 / Shift-JIS.
        assert_eq!(
            eval_str("=ASC(\"\u{FFE5}100\")", &cm, &vs),
            Value::Text("\\100".into())
        );
    }

    #[test]
    fn eval_image_sizing_fit() {
        let (cm, vs) = make_link_env();
        assert_eq!(
            eval_str("=IMAGE(\"u\", \"alt\", 2)", &cm, &vs),
            Value::Text("<IMAGE: u alt=\"alt\" sizing=2>".into())
        );
    }

    #[test]
    fn eval_asc_empty_input() {
        let (cm, vs) = make_test_env();
        assert_eq!(eval_str("=ASC(\"\")", &cm, &vs), Value::Text("".into()));
    }

    #[test]
    fn eval_jis_empty_input() {
        let (cm, vs) = make_test_env();
        assert_eq!(eval_str("=JIS(\"\")", &cm, &vs), Value::Text("".into()));
    }

    #[test]
    fn eval_asc_wrong_arg_count() {
        let (cm, vs) = make_test_env();
        // Zero args.
        assert_eq!(
            eval_str("=ASC()", &cm, &vs),
            Value::Error(ValueError::WrongArgCount)
        );
        // Two args.
        assert_eq!(
            eval_str("=ASC(\"a\",\"b\")", &cm, &vs),
            Value::Error(ValueError::WrongArgCount)
        );
    }

