    fn chisq_env() -> (HashMap<CellAddress, AtomId>, HashMap<AtomId, Value>) {
        // Two 1x4 ranges:
        //   A1:D1 actuals  = 10, 20, 30, 40
        //   A2:D2 expected = 15, 15, 35, 35
        let mut cm: HashMap<CellAddress, AtomId> = HashMap::new();
        let mut vs: HashMap<AtomId, Value> = HashMap::new();
        let actuals = [10.0_f64, 20.0, 30.0, 40.0];
        let expecteds = [15.0_f64, 15.0, 35.0, 35.0];
        let mut next: u64 = 1;
        for (c, (a, e)) in actuals.iter().zip(expecteds.iter()).enumerate() {
            let id_a = AtomId::from_raw(next);
            next += 1;
            cm.insert(CellAddress::new(0, c as u32), id_a);
            vs.insert(id_a, Value::Number(*a));
            let id_e = AtomId::from_raw(next);
            next += 1;
            cm.insert(CellAddress::new(1, c as u32), id_e);
            vs.insert(id_e, Value::Number(*e));
        }
        (cm, vs)
    }

    #[test]
    fn eval_chisq_test_known_value() {
        // χ² = (10-15)²/15 + (20-15)²/15 + (30-35)²/35 + (40-35)²/35
        //    = 25/15 + 25/15 + 25/35 + 25/35 = 50/15 + 50/35 ≈ 4.7619.
        // df = (rows-1)*(cols-1) = 0*3 = 0 → fall through to n-1 = 3.
        use statrs::distribution::{ChiSquared, ContinuousCDF};
        let chi2 = 50.0_f64 / 15.0 + 50.0_f64 / 35.0;
        let expected = 1.0 - ChiSquared::new(3.0).unwrap().cdf(chi2);
        let (cm, vs) = chisq_env();
        match eval_str("=CHISQ.TEST(A1:D1, A2:D2)", &cm, &vs) {
            Value::Number(n) => assert!((n - expected).abs() < 1e-9),
            other => panic!("expected number, got {:?}", other),
        }
        // Legacy alias agrees.
        match eval_str("=CHITEST(A1:D1, A2:D2)", &cm, &vs) {
            Value::Number(n) => assert!((n - expected).abs() < 1e-9),
            other => panic!("expected number, got {:?}", other),
        }
    }

    // ---- P batch: regression + matrix algebra ------------------------
    //
    // The cell-level layout used by `make_math_env` (A=1..5, B=2*A) lets
    // us exercise the linear-regression family directly: slope = 2,
    // intercept = 0 on a perfect fit. Matrix-shaped scenarios live in
    // the dedicated `regression_matrix.rs` integration test file.

    #[test]
    fn eval_linest_perfect_line_returns_slope_and_intercept() {
        let (cm, vs) = make_math_env();
        // y = 2x, x = 1..5. Slope 2, intercept 0.
        match eval_str("=LINEST(B1:B5, A1:A5)", &cm, &vs) {
            Value::Array(arr) => {
                assert_eq!(arr.shape(), (1, 2));
                if let Some(Value::Number(slope)) = arr.get(0, 0) {
                    assert!((slope - 2.0).abs() < 1e-9, "slope {}", slope);
                } else {
                    panic!("expected number slope, got {:?}", arr.get(0, 0));
                }
                if let Some(Value::Number(b)) = arr.get(0, 1) {
                    assert!(b.abs() < 1e-9, "intercept {}", b);
                } else {
                    panic!("expected number intercept, got {:?}", arr.get(0, 1));
                }
            }
            other => panic!("expected Array, got {:?}", other),
        }
    }

    #[test]
    fn eval_linest_stats_block_shape_is_5_x_kplus1() {
        let (cm, vs) = make_math_env();
        match eval_str("=LINEST(B1:B5, A1:A5, TRUE, TRUE)", &cm, &vs) {
            Value::Array(arr) => assert_eq!(arr.shape(), (5, 2)),
            other => panic!("expected 5x2 Array, got {:?}", other),
        }
    }

