    fn frequency_arg_count() {
        let (cm, vs) = make_test_env();
        assert_eq!(
            eval_str("=FREQUENCY({1,2,3})", &cm, &vs),
            Value::Error(ValueError::WrongArgCount)
        );
    }

    #[test]
